// Build ICSE 10 Mathematics ch17 Circles: Tangents, Secants and Intersecting Chords. Run from platform/:
//   npx tsx content/authored/maths/icse-10-mathematics-ch17/src/build.mjs
// Every figure is built by tan.mjs from real coordinates (tangent points are computed exactly, chords and secants are
// placed so that the stated lengths hold): every length label must equal the measured length, every degree label the
// measured angle, every right-angle mark measures 90, and every length or angle that a worked example states or derives
// is asserted against the coordinates (expectLen / expectAng). Every number in a worked example, table, note and
// flashcard is checked line by line by work.mjs (exact arithmetic).
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { setUnit, topic, deck, sl, table, flow, build, chapterTests, r } from './lib.mjs';
import { steps, ARITH, eqctx } from './work.mjs';
import { cfg, must, near, onC, dist, tfig, tanCfg, inChords, extSecants, twoCircles } from './tan.mjs';

setUnit('icse-10-mathematics-ch17');
await import('./questions.mjs');
const DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const A = (lines, msg) => steps(ARITH, lines).must(msg);
const W = (ctx, lines, msg) => steps(ctx, lines).must(msg);
const RT = { right: true };
const S = (deg) => Math.sin((deg * Math.PI) / 180);
const C = (deg) => Math.cos((deg * Math.PI) / 180);
const dg = (n) => `$${n}^\\circ$`;

// ================================================================ deck 1 figures (tangents and touching circles)
const gT1 = cfg({ T: onC(1, 270), P: [-1.3, -1], Q: [1.3, -1] });
const f1Title = tfig({ k: 2, pts: { O: gT1.W.O, T: gT1.W.T, P: gT1.W.P, Q: gT1.W.Q }, circles: [['O', 1]], segs: [['O', 'T'], ['P', 'Q']], angles: [['T', 'O', 'Q', undefined, RT]], pos: { O: 'n' }, expectAng: [['T', 'O', 'Q', 90]] },
  'A circle with centre O. A straight line PQ touches the circle at the point T at the bottom, and the radius OT is drawn from the centre to T. A small square at T marks a right angle between OT and the line.', 'The tangent $PQ$ touches the circle at $T$ and is perpendicular to the radius $OT$.');

const gT3 = cfg({ T: onC(1, 270), P: [-1.3, -1], Q: [1.3, -1], C: onC(1, 160), D: onC(1, 20), _E: [-1.45, S(20)], _F: [1.45, S(20)] });
const f3 = tfig({ k: 2, pts: { O: gT3.W.O, T: gT3.W.T, P: gT3.W.P, Q: gT3.W.Q, C: gT3.W.C, D: gT3.W.D, _E: gT3.W._E, _F: gT3.W._F }, circles: [['O', 1]], segs: [['P', 'Q'], ['_E', '_F']], pos: { O: 'n', C: 'nw', D: 'ne' } },
  'A circle with centre O. A line PQ touches the circle at one point T at the bottom. A second line, drawn above it, cuts the circle at two points C and D and runs on beyond both.', 'The line $PQ$ is a tangent (one point $T$); the line through $C$ and $D$ is a secant (two points).');

const gT4 = cfg({ T: onC(1, 270), P: [-1.3, -1], Q: [1.3, -1], X: [0.9, -1] });
must(dist(gT4.W.O, gT4.W.X) > 1, 'X on the tangent is outside the circle');
const f4 = tfig({ k: 2, pts: { O: gT4.W.O, T: gT4.W.T, P: gT4.W.P, Q: gT4.W.Q, X: gT4.W.X }, circles: [['O', 1]], segs: [['O', 'T'], ['P', 'Q'], ['O', 'X', undefined, { dashed: true }]], angles: [['T', 'O', 'X', undefined, RT]], pos: { O: 'n' }, expectAng: [['T', 'O', 'X', 90]] },
  'A circle with centre O and a tangent PQ touching it at T. The radius OT is drawn, and a dashed line OX joins the centre to another point X of the tangent. OX is longer than OT, and the angle at T is marked as a right angle.', 'Every other point $X$ of the tangent is outside the circle, so $OX > OT$ and $OT$ is the shortest distance to the line.');

const gW1 = tanCfg(20, 29);
const fWE1 = tfig({ k: 0.1, pts: { O: gW1.W.O, T: gW1.W.A, P: gW1.W.P }, circles: [['O', 20]], segs: [['O', 'T', '20 cm'], ['T', 'P', '$?$'], ['O', 'P', '29 cm']], angles: [['T', 'O', 'P', undefined, RT]], pos: { O: 'w', T: 'n' }, expectLen: [['T', 'P', 21], ['O', 'P', 29]] },
  'Worked example 1: a circle with centre O and radius 20 cm. A point P is 29 cm from O, and the tangent PT touches the circle at T with a right angle at T. The length PT is marked with a question mark.', 'Radius $OT = 20$ cm, $OP = 29$ cm; find the tangent $PT$.');
const wk1 = A([r`29^2 - 20^2 = 441`, r`\sqrt{441} = 21`], 'WE1');

const gW2 = tanCfg(1, 1 / C(62));
const fWE2 = tfig({ k: 2.2, pts: { O: gW2.W.O, T: gW2.W.A, P: gW2.W.P }, circles: [['O', 1]], segs: [['O', 'T'], ['T', 'P'], ['O', 'P']], angles: [['O', 'T', 'P', dg(62)], ['P', 'O', 'T', '$?$'], ['T', 'O', 'P', undefined, RT]], pos: { O: 'w', T: 'n' }, expectAng: [['O', 'T', 'P', 62], ['P', 'O', 'T', 28]] },
  'Worked example 2: a circle with centre O and a point P outside it. PT is the tangent at T. The angle POT at the centre is 62 degrees and the angle OPT at P is marked with a question mark.', 'Tangent $PT$ with $\\angle POT = 62^\\circ$; find $\\angle OPT$.');
const wk2 = A([r`180^\circ - 90^\circ - 62^\circ = 28^\circ`], 'WE2');

const g8 = tanCfg(3, 5), w8 = A([r`\sqrt{5^2 - 3^2} = 4`], 'equal tangents');
const f8 = tfig({ k: 0.75, pts: { O: g8.W.O, A: g8.W.A, B: g8.W.B, P: g8.W.P }, circles: [['O', 3]], segs: [['O', 'A', '3 cm'], ['O', 'B', '3 cm'], ['P', 'A', '4 cm', { ticks: 1 }], ['P', 'B', '4 cm', { ticks: 1 }], ['O', 'P', '5 cm', { dashed: true }]], angles: [['A', 'O', 'P', undefined, RT], ['B', 'O', 'P', undefined, RT]], pos: { O: 'w' }, expectLen: [['P', 'A', 4], ['P', 'B', 4], ['O', 'P', 5]] },
  'A circle with centre O and radius 3 cm and a point P that is 5 cm from O. The two tangents PA and PB touch the circle at A and B and are marked equal with one tick each, both 4 cm long. The radii OA and OB are marked at right angles to the tangents and the line OP is dashed.', 'Two tangents from $P$: $PA = PB = 4$ cm.');

const gW3 = tanCfg(1, 1 / S(38));
const fWE3 = tfig({ k: 2.2, pts: { O: gW3.W.O, A: gW3.W.A, B: gW3.W.B, P: gW3.W.P }, circles: [['O', 1]], segs: [['O', 'A'], ['O', 'B'], ['P', 'A'], ['P', 'B'], ['A', 'B']], angles: [['P', 'A', 'B', dg(76)], ['O', 'A', 'B', '$?$'], ['A', 'O', 'P', undefined, RT], ['B', 'O', 'P', undefined, RT]], pos: { O: 'w' }, expectAng: [['O', 'A', 'B', 104], ['A', 'O', 'B', 38], ['A', 'P', 'B', 52]] },
  'Worked example 3: a circle with centre O and a point P outside it. The tangents PA and PB touch the circle at A and B and include an angle of 76 degrees at P. The radii OA and OB and the chord AB are drawn, and the angle AOB is marked with a question mark.', 'Tangents $PA$, $PB$ with $\\angle APB = 76^\\circ$; find $\\angle AOB$, $\\angle OAB$ and $\\angle PAB$.');
const wk3 = A([r`360^\circ - 90^\circ - 90^\circ - 76^\circ = 104^\circ`, r`\dfrac{180^\circ - 104^\circ}{2} = 38^\circ`, r`90^\circ - 38^\circ = 52^\circ`, r`\dfrac{180^\circ - 76^\circ}{2} = 52^\circ`], 'WE3');

const gW4 = tanCfg(48, 50);
const fWE4 = tfig({ k: 0.065, pts: { O: gW4.W.O, A: gW4.W.A, B: gW4.W.B, P: gW4.W.P }, circles: [['O', 48]], segs: [['O', 'A'], ['O', 'B'], ['P', 'A', '$(3x - 4)$ cm'], ['P', 'B', '$(x + 8)$ cm']], angles: [['A', 'O', 'P', undefined, RT], ['B', 'O', 'P', undefined, RT]], pos: { O: 'w' }, expectLen: [['P', 'A', 14], ['P', 'B', 14]] },
  'Worked example 4: a circle with centre O and two tangents PA and PB from the point P. The tangent PA is marked 3x minus 4 centimetres and the tangent PB is marked x plus 8 centimetres.', 'Tangents from $P$: $PA = (3x - 4)$ cm and $PB = (x + 8)$ cm.');
const wk4 = W(eqctx('x', [6]), [r`3x - 4 = x + 8 \Rightarrow 2x = 12 \Rightarrow x = 6`, r`3 \times 6 - 4 = 14`, r`6 + 8 = 14`], 'WE4');

const gExt = cfg({ A: [0, 0], B: [5, 0], T: [3, 0] });
const fExt = tfig({ k: 0.6, pts: { A: gExt.W.A, B: gExt.W.B, T: gExt.W.T }, circles: [['A', 3], ['B', 2]], segs: [['A', 'T', '3 cm'], ['T', 'B', '2 cm']], pos: { A: 'sw', B: 'se', T: 'n' }, expectLen: [['A', 'B', 5]] },
  'Two circles, one with centre A and radius 3 cm and one with centre B and radius 2 cm, that touch each other from outside at the point T. A, T and B lie on one straight line, with AT equal to 3 centimetres and TB equal to 2 centimetres.', 'Touching externally at $T$: $A$, $T$, $B$ are in one line and $AB = 3 + 2 = 5$ cm.');
const gInt = cfg({ A: [0, 0], B: [3, 0], T: [5, 0] });
const fInt = tfig({ k: 0.65, pts: { A: gInt.W.A, B: gInt.W.B, T: gInt.W.T }, circles: [['A', 5], ['B', 2]], segs: [['A', 'B', '3 cm'], ['B', 'T', '2 cm']], pos: { A: 'sw', B: 'sw', T: 'e' }, expectLen: [['A', 'T', 5]] },
  'A circle with centre A and radius 5 cm and a smaller circle with centre B and radius 2 cm inside it that touches it from inside at the point T on the right. A, B and T lie on one straight line, with AB equal to 3 centimetres and BT equal to 2 centimetres.', 'Touching internally at $T$: $A$, $B$, $T$ are in one line and $AB = 5 - 2 = 3$ cm.');

const gW5 = cfg({ A: [0, 0], B: [25, 0], T: [15, 0] });
const fWE5 = tfig({ k: 0.15, pts: { A: gW5.W.A, B: gW5.W.B, T: gW5.W.T }, circles: [['A', 15], ['B', 10]], segs: [['A', 'T', '$x + 5$'], ['T', 'B', '$x$']], pos: { A: 'sw', B: 'se', T: 'n' }, expectLen: [['A', 'B', 25]] },
  'Worked example 5: two circles that touch externally at T, with centres A and B that are 25 centimetres apart. The radius AT of the larger circle is marked x plus 5 and the radius TB of the smaller circle is marked x.', 'Circles touching externally with $AB = 25$ cm; the radii are $x + 5$ and $x$.');
const wk5 = W(eqctx('x', [10]), [r`x + (x + 5) = 25 \Rightarrow 2x + 5 = 25 \Rightarrow x = 10`, r`10 + 5 = 15`, r`15 - 10 = 5`], 'WE5');

const gCd = twoCircles(11, 4, 25, 'direct'), gCt = twoCircles(11, 4, 25, 'transverse');
const wcm = A([r`11 - 4 = 7`, r`\sqrt{25^2 - 7^2} = 24`, r`11 + 4 = 15`, r`\sqrt{25^2 - 15^2} = 20`], 'common tangents');
const fCom = tfig({ k: 0.14, pts: { A: [0, 0], B: [25, 0], P: gCd.W.P, Q: gCd.W.Q, U: gCt.W.P, V: gCt.W.Q }, circles: [['A', 11], ['B', 4]], segs: [['A', 'P', '11 cm'], ['B', 'Q', '4 cm'], ['P', 'Q', '24 cm'], ['U', 'V', '20 cm'], ['A', 'B', undefined, { dashed: true }]], pos: { A: 'sw', B: 'se', P: 'n', Q: 'n', U: 'ne', V: 'sw' }, expectLen: [['P', 'Q', 24], ['U', 'V', 20], ['A', 'B', 25]] },
  'Two circles with centres A and B and radii 11 centimetres and 4 centimetres, 25 centimetres apart. A direct common tangent PQ touches both circles on the upper side and is 24 centimetres long. A transverse common tangent UV crosses the line of centres between the circles and is 20 centimetres long.', 'Centres $25$ cm apart: the direct common tangent $PQ = 24$ cm and the transverse common tangent $UV = 20$ cm.');

const gW6 = twoCircles(18, 3, 25, 'direct');
const fWE6 = tfig({ k: 0.12, pts: { A: [0, 0], B: [25, 0], P: gW6.W.P, Q: gW6.W.Q }, circles: [['A', 18], ['B', 3]], segs: [['A', 'P', '18 cm'], ['B', 'Q', '3 cm'], ['P', 'Q', '$?$'], ['A', 'B', '25 cm', { dashed: true }]], angles: [['P', 'A', 'Q', undefined, RT], ['Q', 'B', 'P', undefined, RT]], pos: { A: 'sw', B: 'se', P: 'n', Q: 'n' }, expectLen: [['P', 'Q', 20], ['A', 'B', 25]] },
  'Worked example 6: two circles with centres A and B and radii 18 centimetres and 3 centimetres, whose centres are 25 centimetres apart. A direct common tangent PQ touches them at P and Q, with the radii AP and BQ marked at right angles to it. The length PQ is marked with a question mark.', 'Radii $18$ cm and $3$ cm, $AB = 25$ cm; find the direct common tangent $PQ$.');
const wk6 = A([r`18 - 3 = 15`, r`\sqrt{25^2 - 15^2} = 20`], 'WE6');

const fFlow1 = flow('TB', [['s', 'A tangent or touching circles appears in the figure: what is given?'], ['a', 'A radius to the point of contact: it meets the tangent at 90 degrees'], ['b', 'Two tangents from one point: equal lengths, and use the right angles at A and B'], ['c', 'Two circles touching: the centres and the point of contact are in one line'], ['d', 'A common tangent: right triangle with legs d and r1 minus r2 or r1 plus r2']], [['s', 'a'], ['s', 'b'], ['s', 'c'], ['c', 'd']],
  'Flow chart for tangent problems: start from what is given; a radius to the point of contact is perpendicular to the tangent; two tangents from a point are equal; touching circles have the centres and the point of contact on one line; a common tangent is found from a right triangle whose legs are the line of centres and the difference or sum of the radii.', 'Match the figure to the property.');
const tProps1 = table(['Result', 'In words', 'Used for'], [['Tangent and radius', 'the radius to the point of contact is perpendicular to the tangent', 'right-angled triangles and Pythagoras'], ['Two tangents from a point', 'equal in length', 'lengths and isosceles triangles'], ['Touching circles', 'centres and point of contact are in one line', 'distance between the centres'], ['Common tangent', 'right triangle on the line of centres', 'length of the common tangent']], 'Table of the results in part 1: a tangent is perpendicular to the radius at the point of contact; the two tangents from a point are equal; touching circles have the point of contact on the line of centres; a common tangent is found from a right triangle.', 'Part 1: tangents and touching circles.');
const tSum1 = table(['Situation', 'Fact', 'Formula'], [['Tangent length', 'radius perpendicular to tangent', r`$PT = \sqrt{OP^2 - r^2}$`], ['Two tangents from P', 'PA = PB, and OP bisects the angle APB', r`$\angle AOB = 180^\circ - \angle APB$`], ['Touch externally', 'centres apart by the sum of radii', r`$d = r_1 + r_2$`], ['Touch internally', 'centres apart by the difference of radii', r`$d = r_1 - r_2$`], ['Common tangents', 'right triangle with the line of centres', r`$\sqrt{d^2 - (r_1 \mp r_2)^2}$`]], 'Summary table for part 1: tangent length is the square root of OP squared minus the radius squared; the two tangents from a point are equal; centres of externally touching circles are the sum of the radii apart and of internally touching circles the difference; common tangent lengths come from the square root of d squared minus the sum or difference of the radii squared.', 'Part 1 on one card.');

// ================================================================ deck 2 figures (chords, secants, alternate segment)
const gTitle2 = inChords(10, 6, 10, 12, 5), wt2 = A([r`6 \times 10 = 60`, r`12 \times 5 = 60`], 'title 2');
const f2Title = tfig({ k: 0.3, pts: gTitle2.W, circles: [['O', 10]], segs: [['A', 'P', '6 cm'], ['P', 'B', '10 cm'], ['C', 'P', '12 cm'], ['P', 'D', '5 cm']], pos: { O: 'n', P: 'n' }, expectLen: [['P', 'A', 6], ['P', 'B', 10], ['P', 'C', 12], ['P', 'D', 5]] },
  'A circle with centre O and two chords AB and CD that cross at a point P inside it. The parts of AB are 6 centimetres and 10 centimetres, and the parts of CD are 12 centimetres and 5 centimetres.', 'Chords crossing at $P$: $6 \\times 10 = 60 = 12 \\times 5$.');

const gCh = inChords(9, 5, 12, 6, 10), wch = A([r`5 \times 12 = 60`, r`6 \times 10 = 60`], 'chords');
const fChords = tfig({ k: 0.35, pts: gCh.W, circles: [['O', 9]], segs: [['A', 'P', '5 cm'], ['P', 'B', '12 cm'], ['C', 'P', '6 cm'], ['P', 'D', '10 cm']], pos: { O: 'n', P: 'n' }, expectLen: [['P', 'A', 5], ['P', 'B', 12], ['P', 'C', 6], ['P', 'D', 10]] },
  'A circle with centre O and two chords AB and CD that cross at the point P inside it. PA is 5 centimetres, PB is 12 centimetres, PC is 6 centimetres and PD is 10 centimetres.', 'Intersecting chords: $PA \\times PB = PC \\times PD$, here $5 \\times 12 = 6 \\times 10$.');
must(near(gCh.ang('A', 'C', 'P'), gCh.ang('D', 'B', 'P')) && near(gCh.ang('C', 'A', 'P'), gCh.ang('B', 'D', 'P')), 'proof: equal angles in the same segment');
const fProofCh = tfig({ k: 0.35, pts: gCh.W, circles: [['O', 9]], segs: [['A', 'P'], ['P', 'B'], ['C', 'P'], ['P', 'D'], ['A', 'C', undefined, { dashed: true }], ['D', 'B', undefined, { dashed: true }]], angles: [['A', 'C', 'P', undefined, { arcs: 1 }], ['D', 'B', 'P', undefined, { arcs: 1 }], ['C', 'A', 'P', undefined, { arcs: 2 }], ['B', 'D', 'P', undefined, { arcs: 2 }]], pos: { O: 'n', P: 'n' } },
  'A circle with two chords AB and CD that cross at P. The points A and C are joined and the points D and B are joined with dashed lines, forming two triangles PAC and PDB. The angles at A and D carry one arc each and the angles at C and B carry two arcs each, to show that they are equal.', 'Triangles $PAC$ and $PDB$ are similar (equal angles in the same segment).');

const gWD1 = inChords(10, 15, 4, 5, 12), wd1 = A([r`15 \times 4 = 60`, r`\dfrac{60}{5} = 12`], 'chords WE1');
const fWD1 = tfig({ k: 0.3, pts: gWD1.W, circles: [['O', 10]], segs: [['A', 'P', '15 cm'], ['P', 'B', '4 cm'], ['C', 'P', '5 cm'], ['P', 'D', '$?$']], pos: { O: 'n', P: 'n' }, expectLen: [['P', 'D', 12]] },
  'Worked example 1: two chords AB and CD of a circle that cross at P. PA is 15 centimetres, PB is 4 centimetres and PC is 5 centimetres; PD is marked with a question mark.', 'Chords $AB$ and $CD$ cut at $P$; find $PD$.');
const gWD2 = inChords(8, 6, 4, 2, 12), wd2 = W(eqctx('x', [3]), [r`2x(x + 1) = 2 \times 12 \Rightarrow x^2 + x - 12 = 0 \Rightarrow (x + 4)(x - 3) = 0 \Rightarrow x = 3`, r`2 \times 3 = 6`, r`3 + 1 = 4`, r`6 + 4 = 10`, r`2 + 12 = 14`], 'chords WE2');
const fWD2 = tfig({ k: 0.38, pts: gWD2.W, circles: [['O', 8]], segs: [['A', 'P', '$2x$'], ['P', 'B', '$x + 1$'], ['C', 'P', '2 cm'], ['P', 'D', '12 cm']], pos: { O: 'n', P: 'n' }, expectLen: [['P', 'A', 6], ['P', 'B', 4], ['A', 'B', 10], ['C', 'D', 14]] },
  'Worked example 2: two chords AB and CD of a circle that cross at P. The parts of AB are marked 2x and x plus 1, and the parts of CD are 2 centimetres and 12 centimetres.', 'Chords $AB$ and $CD$ cut at $P$: $PA = 2x$, $PB = x + 1$, $PC = 2$ cm, $PD = 12$ cm.');

const gSec = extSecants(Math.sqrt(61), 11, 5, 12, 6, 10), wsec = A([r`5 \times 12 = 60`, r`6 \times 10 = 60`], 'secants');
const fSec = tfig({ k: 0.33, pts: { O: gSec.W.O, P: gSec.W.P, A: gSec.W.A, B: gSec.W.B, C: gSec.W.C, D: gSec.W.D }, circles: [['O', Math.sqrt(61)]], segs: [['P', 'A', '5 cm'], ['P', 'B', '12 cm'], ['P', 'C', '6 cm'], ['P', 'D', '10 cm']], pos: { O: 'w' }, expectLen: [['P', 'A', 5], ['P', 'B', 12], ['P', 'C', 6], ['P', 'D', 10]] },
  'A circle with centre O and a point P outside it. Two lines from P cut the circle. The first meets it at A, 5 centimetres from P, and then at B, 12 centimetres from P. The second meets it at C, 6 centimetres from P, and then at D, 10 centimetres from P.', 'Chords $AB$ and $CD$ produced meet at $P$: $PA \\times PB = PC \\times PD$.');
const fWD3 = tfig({ k: 0.33, pts: { O: gSec.W.O, P: gSec.W.P, A: gSec.W.A, B: gSec.W.B, C: gSec.W.C, D: gSec.W.D }, circles: [['O', Math.sqrt(61)]], segs: [['P', 'A', '5 cm'], ['A', 'B', '7 cm'], ['P', 'C', '6 cm'], ['C', 'D', '$?$']], pos: { O: 'w' }, expectLen: [['P', 'D', 10], ['C', 'D', 4]] },
  'Worked example 3: a circle and a point P outside it. One line from P meets the circle at A and B with PA equal to 5 centimetres and AB equal to 7 centimetres. A second line meets it at C and D with PC equal to 6 centimetres; the length CD is marked with a question mark.', 'Chords produced meet at $P$: $PA = 5$ cm, $AB = 7$ cm, $PC = 6$ cm; find $CD$.');
const wd3 = A([r`5 + 7 = 12`, r`5 \times 12 = 60`, r`\dfrac{60}{6} = 10`, r`10 - 6 = 4`], 'secants WE3');

const gTS = extSecants(40, 50, 20, 45), wts = A([r`20 \times 45 = 900`, r`30^2 = 900`], 'tangent-secant');
const fTS = tfig({ k: 0.07, pts: { O: gTS.W.O, P: gTS.W.P, A: gTS.W.A, B: gTS.W.B, T: gTS.W.T }, circles: [['O', 40]], segs: [['P', 'T', '30 cm'], ['P', 'A', '20 cm'], ['P', 'B', '45 cm'], ['O', 'T', undefined, { dashed: true }]], angles: [['T', 'O', 'P', undefined, RT]], pos: { O: 'w' }, expectLen: [['P', 'T', 30], ['P', 'A', 20], ['P', 'B', 45]] },
  'A circle with centre O and a point P outside it. The tangent PT touches the circle at T and is 30 centimetres long. A secant from P meets the circle at A, 20 centimetres from P, and at B, 45 centimetres from P. The radius OT is dashed and marked at right angles to PT.', 'Tangent $PT = 30$ cm and secant $PAB$: $PT^2 = 900 = 20 \\times 45 = PA \\times PB$.');
must(near(gTS.len('P', 'T') ** 2, gTS.len('P', 'A') * gTS.len('P', 'B')), 'PT^2 = PA.PB');

const gWD4 = extSecants(15, 25, 16, 25), wd4 = A([r`20^2 = 400`, r`\dfrac{400}{16} = 25`, r`25 - 16 = 9`], 'TS WE4');
const fWD4 = tfig({ k: 0.15, pts: { O: gWD4.W.O, P: gWD4.W.P, A: gWD4.W.A, B: gWD4.W.B, T: gWD4.W.T }, circles: [['O', 15]], segs: [['P', 'T', '20 cm'], ['P', 'A', '16 cm'], ['A', 'B', '$?$']], pos: { O: 'w' }, expectLen: [['P', 'T', 20], ['P', 'B', 25], ['A', 'B', 9]] },
  'Worked example 4: a circle with a point P outside it. The tangent PT is 20 centimetres long. A secant from P meets the circle at A, 16 centimetres from P, and at B. The chord AB is marked with a question mark.', 'Tangent $PT = 20$ cm, $PA = 16$ cm; find the chord $AB$.');

const gWD5 = extSecants(13, Math.sqrt(250), 3, 27), wd5 = W(eqctx('x', [3]), [r`x(x + 24) = 9^2 \Rightarrow x^2 + 24x - 81 = 0 \Rightarrow (x + 27)(x - 3) = 0 \Rightarrow x = 3`, r`3 + 24 = 27`, r`3 \times 27 = 81`], 'TS WE5');
const fWD5 = tfig({ k: 0.2, pts: { O: gWD5.W.O, P: gWD5.W.P, A: gWD5.W.A, B: gWD5.W.B, T: gWD5.W.T }, circles: [['O', 13]], segs: [['P', 'T', '9 cm'], ['P', 'A', '$x$'], ['A', 'B', '24 cm']], pos: { O: 'w' }, expectLen: [['P', 'T', 9], ['P', 'A', 3], ['P', 'B', 27]] },
  'Worked example 5: a circle with a point P outside it. The tangent PT is 9 centimetres long. A secant from P meets the circle at A and B, with PA marked x and the chord AB marked 24 centimetres.', 'Tangent $PT = 9$ cm; $PA = x$ and $AB = 24$ cm.');

const altG = (arcTA) => { const T = onC(1, 270); return cfg({ T, A: onC(1, 270 + arcTA), B: onC(1, 140), D: onC(1, 90), P: [T[0] + 0.8, T[1]], Q: [T[0] - 0.8, T[1]] }); };
const gAlt = altG(96);
const fAlt = tfig({ k: 2.2, pts: { O: gAlt.W.O, T: gAlt.W.T, A: gAlt.W.A, B: gAlt.W.B, P: gAlt.W.P, Q: gAlt.W.Q }, circles: [['O', 1]], segs: [['P', 'Q'], ['T', 'A'], ['T', 'B'], ['B', 'A']], angles: [['T', 'P', 'A', dg(48), { arcs: 1 }], ['B', 'T', 'A', dg(48), { arcs: 1 }]], pos: { O: 'w' }, expectAng: [['T', 'P', 'A', 48], ['B', 'T', 'A', 48]] },
  'A circle with a horizontal tangent PQ touching it at T at the bottom. The chord TA goes up to the right. The angle between the tangent TP and the chord TA is 48 degrees. A point B on the other side of the chord, in the alternate segment, is joined to T and A, and the angle TBA is also 48 degrees.', 'Angle between tangent and chord $= 48^\\circ = $ angle in the alternate segment.');
const fAltProof = tfig({ k: 2.2, pts: { O: gAlt.W.O, T: gAlt.W.T, A: gAlt.W.A, D: gAlt.W.D, P: gAlt.W.P, Q: gAlt.W.Q }, circles: [['O', 1]], segs: [['P', 'Q'], ['T', 'D'], ['T', 'A'], ['A', 'D']], angles: [['A', 'T', 'D', undefined, RT], ['T', 'P', 'D', undefined, RT]], pos: { O: 'e' }, expectAng: [['A', 'T', 'D', 90], ['T', 'P', 'D', 90], ['T', 'A', 'D', 42], ['D', 'T', 'A', 48]] },
  'A circle with a horizontal tangent PQ touching it at T at the bottom. The diameter TD goes straight up through the centre O to D at the top, and the chord TA and the line AD are drawn. The angle at T between the tangent and the diameter is marked as a right angle, and so is the angle TAD at A.', 'With the diameter $TD$: $\\angle PTD = 90^\\circ$ and $\\angle TAD = 90^\\circ$ (semicircle).');
const wal = A([r`90^\circ - 48^\circ = 42^\circ`, r`90^\circ - 42^\circ = 48^\circ`], 'alternate proof');

const gW6d = (() => { const Tt = onC(1, 270); return cfg({ A: Tt, B: onC(1, 46), C: onC(1, 176), P: [Tt[0] + 0.9, Tt[1]], Q: [Tt[0] - 0.9, Tt[1]] }); })();
const fWD6 = tfig({ k: 2, pts: { O: gW6d.W.O, A: gW6d.W.A, B: gW6d.W.B, C: gW6d.W.C, P: gW6d.W.P, Q: gW6d.W.Q }, circles: [['O', 1]], segs: [['P', 'Q'], ['A', 'B'], ['A', 'C'], ['B', 'C']], angles: [['C', 'A', 'B', dg(68), { arcs: 1 }], ['B', 'A', 'C', dg(47), { arcs: 2 }], ['A', 'P', 'B', '$?$'], ['A', 'Q', 'C', '$?$']], pos: { O: 'n' }, expectAng: [['A', 'P', 'B', 68], ['A', 'Q', 'C', 47], ['A', 'B', 'C', 65]] },
  'Worked example 6: a circle through A, B and C with the tangent PQ at A. The angle ACB is marked 68 degrees and the angle ABC is marked 47 degrees. The angles PAB and QAC between the tangent and the two chords are marked with question marks.', 'Triangle $ABC$ in a circle with the tangent $PQ$ at $A$; $\\angle ACB = 68^\\circ$, $\\angle ABC = 47^\\circ$.');
const wd6 = A([r`180^\circ - 68^\circ - 47^\circ = 65^\circ`, r`68^\circ + 65^\circ + 47^\circ = 180^\circ`], 'alt WE6');

const fFlow2 = flow('TB', [['s', 'Chords, secants or a tangent in the figure: which lengths or angles are given?'], ['a', 'Two chords cutting inside the circle: PA times PB equals PC times PD'], ['b', 'Two secants from an outside point: PA times PB equals PC times PD'], ['c', 'A tangent and a secant from one point: PT squared equals PA times PB'], ['d', 'An angle between a tangent and a chord: equal to the angle in the alternate segment']], [['s', 'a'], ['s', 'b'], ['s', 'c'], ['s', 'd']],
  'Flow chart for choosing a theorem: two chords cutting inside the circle give PA times PB equals PC times PD; two secants from an outside point give the same product rule; a tangent and a secant give PT squared equals PA times PB; an angle between a tangent and a chord equals the angle in the alternate segment.', 'Match the figure to the theorem.');
const tProps2 = table(['Theorem', 'In words', 'Figure'], [['Intersecting chords', 'PA times PB equals PC times PD', 'two chords crossing inside'], ['Secants from a point', 'PA times PB equals PC times PD', 'two secants from outside'], ['Tangent and secant', 'PT squared equals PA times PB', 'one tangent and one secant'], ['Alternate segment', 'tangent-chord angle equals the angle in the alternate segment', 'a tangent and chords from the point of contact']], 'Table of the results in part 2: the product of the parts of two intersecting chords is equal; the same rule holds for two secants from an outside point; the square of a tangent equals the product of a secant and its outer part; the angle between a tangent and a chord equals the angle in the alternate segment.', 'Part 2: chords, secants and the alternate segment.');
const tSum2 = table(['Theorem', 'Statement', 'Typical use'], [['Intersecting chords', r`$PA \times PB = PC \times PD$`, 'find a missing part of a chord'], ['Two secants', r`$PA \times PB = PC \times PD$ ($PB$, $PD$ from $P$ to the far end)`, 'find a secant or a chord'], ['Tangent and secant', r`$PT^2 = PA \times PB$`, 'find a tangent or a secant'], ['Alternate segment', r`tangent-chord angle $=$ angle in the alternate segment`, 'find angles in a triangle in a circle']], 'Summary table for part 2: the intersecting chords and two secants rules give PA times PB equals PC times PD; the tangent and secant rule gives PT squared equals PA times PB; the alternate segment theorem equates the tangent-chord angle with the angle in the alternate segment.', 'Part 2 on one card.');

// ================================================================ decks
const d1 = deck({
  part: 1,
  title: 'Circles: Tangents — Part 1: Tangent and radius, two tangents, touching circles',
  goals: ['Prove that a tangent is perpendicular to the radius at the point of contact and use it with Pythagoras', 'Prove that two tangents from an external point are equal and use the right angles at the points of contact', 'Find the distance between the centres of circles that touch externally or internally', 'Find the length of a common tangent of two circles'],
  slides: [
    sl('title', 'Circles: tangents, Part 1', { b: 'A **tangent** touches a circle at exactly one point, and it always meets the radius to that point at a **right angle**. In this part we prove that, and use it for lengths, angles and touching circles.', v: f1Title, n: 'Welcome to tangents. A tangent is a line that touches a circle at just one point. Look at the picture: the radius drawn to the point of contact meets the tangent at a right angle. In this part we prove that, then use it to find lengths and angles, to study two tangents from a point, and to work with circles that touch each other.' }),
    sl('concept', 'What you will be able to do', { ul: ['Prove that a **tangent is perpendicular to the radius**', 'Use it with **Pythagoras** to find lengths', 'Prove that **two tangents from a point are equal**', 'Work with **touching circles** and common tangents'], v: tProps1, n: 'These are your goals for part one. We prove that a tangent is perpendicular to the radius and use it with the theorem of Pythagoras. We prove that two tangents from a point are equal. Then we study circles that touch, and find the length of a common tangent. The table shows the four results on one card.' }),
    sl('concept', 'Tangent and secant', { b: 'A line that meets a circle at **two points** is a **secant**; a line that meets it at **one point** only is a **tangent**, and that point is the **point of contact**.', ul: ['a chord is the part of a secant inside the circle', 'a tangent never enters the circle'], v: f3, n: 'First the words. A line that cuts a circle at two points is called a secant. A line that touches a circle at one point only is called a tangent, and the point is the point of contact. A chord is the part of a secant that lies inside the circle. A tangent never enters the circle: every other point of it is outside.' }),
    sl('concept', 'A tangent is perpendicular to the radius', { b: 'The tangent at a point of a circle is **perpendicular to the radius** drawn to the point of contact.', m: [r`OT \perp PQ`], ul: ['**Proof:** take any point $X$ of the tangent other than $T$; $X$ is outside the circle, so $OX > OT$', '$OT$ is shorter than every other segment from $O$ to the line, and the **shortest** segment from a point to a line is the **perpendicular**', 'so $OT \\perp PQ$'], v: f4, n: 'Here is the theorem. The tangent is perpendicular to the radius at the point of contact. To prove it, take any other point X on the tangent. It is outside the circle, so the distance O X is longer than the radius O T. So O T is the shortest distance from the centre to the line. The shortest distance from a point to a line is the perpendicular, so O T is perpendicular to the tangent.' }),
    sl('example', 'Worked example 1: the length of a tangent', { b: 'The point $P$ is $29$ cm from the centre $O$ of a circle of radius $20$ cm, and $PT$ is the tangent from $P$. Find $PT$.', ul: ['**Step 1 —** $OT \\perp PT$, so $\\triangle OTP$ is right-angled at $T$', `**Step 2 —** $PT^2 = OP^2 - OT^2 = ${wk1.lines[0]}$`, `**Step 3 —** $PT = ${wk1.lines[1]}$ cm`], v: fWE1, n: 'The radius to the point of contact is perpendicular to the tangent, so the triangle O T P has a right angle at T. By the theorem of Pythagoras, P T squared is O P squared minus O T squared. That is twenty nine squared minus twenty squared, which is four hundred and forty one. The square root of four hundred and forty one is twenty one, so the tangent is twenty one centimetres long.' }),
    sl('check', 'Quick check: a cable to a drum', { b: 'Use the right angle at the point of contact.', chk: 'm02', n: 'A cable touches a drum. Use the right angle between the radius and the tangent, then the theorem of Pythagoras.' }),
    sl('example', 'Worked example 2: an angle in the right triangle', { b: '$PT$ is a tangent at $T$ to a circle with centre $O$, and $\\angle POT = 62^\\circ$. Find $\\angle OPT$.', ul: ['**Step 1 —** $\\angle OTP = 90^\\circ$ (tangent and radius)', `**Step 2 —** the angles of $\\triangle OTP$: $\\angle OPT = ${wk2.lines[0]}$`], v: fWE2, n: 'The tangent is perpendicular to the radius, so the angle at T in the triangle O T P is ninety degrees. The angle at O is sixty two degrees. The three angles of a triangle add up to one hundred and eighty, so the angle at P is one hundred and eighty minus ninety minus sixty two, which is twenty eight degrees.' }),
    sl('concept', 'Two tangents from a point are equal', { b: 'The two tangents drawn to a circle from an **external point** are **equal** in length, and each makes a **right angle** with its radius.', m: [r`PA = PB`], ul: ['**Proof:** in the right-angled triangles $OAP$ and $OBP$: $OA = OB$ (radii), $OP$ is common, and $\\angle OAP = \\angle OBP = 90^\\circ$', 'so the triangles are congruent (RHS) and $PA = PB$', '$OP$ also bisects $\\angle APB$ and $\\angle AOB$; here $PA = \\sqrt{5^2 - 3^2} = 4$ cm'], v: f8, n: 'Here are two tangents from one point P. They touch the circle at A and B. In the right angled triangles O A P and O B P, the radii O A and O B are equal, the side O P is shared, and the angles at A and B are right angles. So the triangles are congruent, and P A equals P B. In the picture both tangents are four centimetres long.' }),
    sl('example', 'Worked example 3: angles at the centre', { b: 'The tangents $PA$ and $PB$ from $P$ include $\\angle APB = 76^\\circ$. Find $\\angle AOB$, $\\angle OAB$ and $\\angle PAB$.', ul: [`**Step 1 —** $\\angle OAP = \\angle OBP = 90^\\circ$, so in the quadrilateral $OAPB$: $\\angle AOB = ${wk3.lines[0]}$`, `**Step 2 —** $OA = OB$, so $\\angle OAB = ${wk3.lines[1]}$`, `**Step 3 —** $\\angle PAB = ${wk3.lines[2]}$ (check: $PA = PB$, so $\\angle PAB = ${wk3.lines[3]}$)`], v: fWE3, n: 'The angles at A and B are right angles, so in the quadrilateral O A P B, the angle at O is three hundred and sixty minus ninety minus ninety minus seventy six, one hundred and four degrees. The radii are equal, so each base angle of the triangle O A B is one hundred and eighty minus one hundred and four, halved, thirty eight degrees. The angle P A B is ninety minus thirty eight, fifty two degrees.' }),
    sl('check', 'Quick check: the angle between the tangents', { b: 'A quadrilateral has four angles adding to $360^\\circ$.', chk: 'm03', n: 'The angle at the centre is given. Use the two right angles and the angle sum of the quadrilateral to find the angle between the tangents.' }),
    sl('example', 'Worked example 4: equal tangents with algebra', { b: 'The tangents from $P$ are $PA = (3x - 4)$ cm and $PB = (x + 8)$ cm. Find $x$ and the length of each tangent.', ul: [`**Step 1 —** equal tangents: ${wk4.md[0]}`, `**Step 2 —** $PA = ${wk4.lines[1]}$ cm`, `**Step 3 —** $PB = ${wk4.lines[2]}$ cm, the same length`], v: fWE4, n: 'The two tangents from one point are equal. So three x minus four equals x plus eight. That gives two x equals twelve, so x is six. The first tangent is three times six minus four, which is fourteen centimetres. The second is six plus eight, also fourteen centimetres, so the check works.' }),
    sl('concept', 'Circles that touch externally', { b: 'Two circles **touch externally** at one point $T$. The centres and $T$ lie on **one straight line**, with $T$ between the centres.', m: [r`d = r_1 + r_2`], ul: ['the distance between the centres is the **sum** of the radii', 'the common tangent at $T$ is perpendicular to the line of centres'], v: fExt, n: 'Now touching circles. When two circles touch from outside, the two centres and the point of contact lie on one straight line, with the point of contact between the centres. So the distance between the centres is the sum of the radii. Here three plus two gives five centimetres. The tangent they share at the point of contact is perpendicular to the line of centres.' }),
    sl('concept', 'Circles that touch internally', { b: 'Two circles **touch internally** when one lies inside the other and they meet at one point $T$. The centres and $T$ lie on **one straight line**, with both centres on the same side of $T$.', m: [r`d = r_1 - r_2`], ul: ['the distance between the centres is the **difference** of the radii', 'the smaller circle is wholly inside the larger one'], v: fInt, n: 'When one circle touches another from inside, the centres and the point of contact are again on one line, but now both centres are on the same side of the point of contact. The distance between the centres is the difference of the radii. Here five minus two gives three centimetres, and the smaller circle lies wholly inside the larger one.' }),
    sl('example', 'Worked example 5: radii from the distance', { b: 'Two circles touch externally and their centres are $25$ cm apart. One radius is $5$ cm longer than the other. Find the radii, and the distance between the centres if they touched internally.', ul: [`**Step 1 —** radii $x$ and $x + 5$: ${wk5.md[0]}`, `**Step 2 —** the radii are $${wk5.lines[1]}$ cm and $10$ cm`, `**Step 3 —** internal contact: $d = ${wk5.lines[2]}$ cm`], v: fWE5, n: 'Let the smaller radius be x, so the larger is x plus five. For external contact the distance between the centres is the sum, so x plus x plus five equals twenty five. That gives x equal to ten, so the radii are ten and fifteen centimetres. If the same circles touched internally, the distance would be the difference, fifteen minus ten, which is five centimetres.' }),
    sl('concept', 'Common tangents of two circles', { b: 'A line that touches **both** circles is a **common tangent**. Draw the radii to the points of contact and a line parallel to the tangent: this makes a **right-angled triangle** on the line of centres.', m: [r`\text{direct: } \sqrt{d^2 - (r_1 - r_2)^2}, \quad \text{transverse: } \sqrt{d^2 - (r_1 + r_2)^2}`], ul: [`here $d = 25$, $r_1 = 11$, $r_2 = 4$: $${wcm.lines[1]}$ for the direct tangent and $${wcm.lines[3]}$ for the transverse tangent`], v: fCom, n: 'A line touching both circles is a common tangent. A direct common tangent has both circles on the same side. A transverse one crosses between the circles. In each case a right angled triangle appears. Its hypotenuse is the line of centres, and its other side is the difference of the radii for a direct tangent, or the sum of the radii for a transverse tangent. Here that gives twenty four and twenty.' }),
    sl('example', 'Worked example 6: a belt round two wheels', { b: 'Two wheels of radii $18$ cm and $3$ cm have their centres $25$ cm apart. A tight belt touches both on the same side. Find the straight length $PQ$ of the belt.', ul: [`**Step 1 —** draw the right triangle: legs $PQ$ and $r_1 - r_2 = ${wk6.lines[0]}$ cm, hypotenuse $25$ cm`, `**Step 2 —** $PQ = ${wk6.lines[1]}$ cm`], v: fWE6, n: 'The belt touches both wheels on the same side, so it is a direct common tangent. Draw a line from the smaller centre parallel to the belt. This makes a right angled triangle with hypotenuse twenty five, the line of centres, and one side equal to the difference of the radii, eighteen minus three, fifteen. The belt is the square root of twenty five squared minus fifteen squared, which is twenty centimetres.' }),
    sl('check', 'Quick check: gear wheels', { b: 'Externally touching: sum of the radii.', chk: 'm05', n: 'Two wheels touch each other from outside. Add the radii to find the distance between the centres.' }),
    sl('concept', 'Which property should I use?', { b: 'Look for a **radius to a point of contact**, **two tangents from a point** or **touching circles**, then use the matching fact.', v: fFlow1, n: 'To choose a property, look at the figure. A radius to a point of contact means a right angle. Two tangents from one point means equal lengths and two right angles. Two touching circles mean the centres and the point of contact are on one line. For a common tangent, build the right angled triangle on the line of centres.' }),
    sl('summary', 'Summary', { ul: ['Tangent $\\perp$ radius at the point of contact', 'Tangent length $= \\sqrt{OP^2 - r^2}$', 'Two tangents from a point: equal, and $OP$ bisects the angle', 'Touching circles: $d = r_1 + r_2$ (outside), $d = r_1 - r_2$ (inside)', 'Common tangents: right triangle on the line of centres'], v: tSum1, n: 'To sum up part one. A tangent is perpendicular to the radius at the point of contact. Use that with Pythagoras to find tangent lengths. Two tangents from a point are equal. Circles that touch have their centres and the point of contact on one line, so the distance is the sum or the difference of the radii. A common tangent comes from a right angled triangle on the line of centres.' }),
    sl('exam-tips', 'Exam tips: how marks are awarded', { ul: ['**Reason (1 mark):** write "tangent perpendicular to radius" or "tangents from a point are equal" beside the step', '**Working (1–2 marks):** the Pythagoras line or the angle sum, with the numbers shown', '**Answer with unit (1 mark):** cm or degrees', '**Mistake:** forgetting the right angle at the point of contact', '**Mistake:** using the sum of the radii for internal contact', '**Habit:** mark the right angles and equal tangents on the figure first'], n: 'In the exam, write the reason beside each step, for example tangent perpendicular to radius. Show the Pythagoras line or the angle sum with the numbers. Give the answer with its unit. Common slips are forgetting the right angle at the point of contact, and using the sum of the radii when the circles touch from inside. Mark right angles and equal tangents on the figure first.' }),
  ],
});

const d2 = deck({
  part: 2,
  title: 'Circles: Chords, Secants and Tangent — Part 2: Product of segments and the alternate segment theorem',
  goals: ['Prove and use the intersecting chords theorem', 'Use the same product rule for secants that meet outside the circle', 'Prove and use the tangent-secant theorem', 'Prove and use the alternate segment theorem to find angles'],
  slides: [
    sl('title', 'Circles: chords and tangents, Part 2', { b: 'When two chords cross inside a circle, the **products of their parts are equal**. In this part we prove that, extend it to secants and tangents, and finish with the **alternate segment theorem**.', v: f2Title, n: 'Welcome to part two. Two chords of a circle cross at a point. Multiply the two parts of one chord, six times ten, and you get sixty. Multiply the parts of the other chord, twelve times five, and you also get sixty. In this part we prove that, extend it to secants and tangents, and then study the angle between a tangent and a chord.' }),
    sl('concept', 'What you will be able to do', { ul: ['Prove and use the **intersecting chords** theorem', 'Use the same rule for **secants** from an outside point', 'Prove and use **tangent squared equals product of a secant**', 'Prove and use the **alternate segment** theorem'], v: tProps2, n: 'These are your goals for part two. We prove the intersecting chords theorem. We use the same product rule for secants from an outside point, then prove that the square of a tangent equals a product. Finally we prove the alternate segment theorem and use it to find angles. The table shows all four results.' }),
    sl('concept', 'Intersecting chords', { b: 'If two chords $AB$ and $CD$ of a circle **cut at a point $P$ inside** the circle, then the **product of the parts** of one chord equals the product of the parts of the other.', m: [r`PA \times PB = PC \times PD`], ul: [`here ${wch.md[0]} and ${wch.md[1]}`], v: fChords, n: 'The intersecting chords theorem says: if two chords cut at a point P inside the circle, the product of the two parts of one chord equals the product of the two parts of the other. In the picture, five times twelve is sixty, and six times ten is also sixty. The product is the same for every chord through P.' }),
    sl('concept', 'Proof of the intersecting chords theorem', { b: 'Join $AC$ and $DB$. In $\\triangle PAC$ and $\\triangle PDB$:', ul: ['$\\angle CAP = \\angle BDP$ (angles in the same segment on the chord $CB$)', '$\\angle ACP = \\angle DBP$ (angles in the same segment on the chord $AD$)', 'so the triangles are **similar** and $\\dfrac{PA}{PD} = \\dfrac{PC}{PB}$', 'cross-multiplying: $PA \\times PB = PC \\times PD$'], v: fProofCh, n: 'To prove it, join A to C and D to B. The angles at A and D stand on the same chord C B, so they are equal. The angles at C and B stand on the same chord A D, so they are equal too. The triangles P A C and P D B are therefore similar. So P A over P D equals P C over P B, and cross multiplying gives P A times P B equals P C times P D.' }),
    sl('example', 'Worked example 1: a missing part', { b: 'Chords $AB$ and $CD$ cut at $P$ with $PA = 15$ cm, $PB = 4$ cm and $PC = 5$ cm. Find $PD$.', ul: ['**Step 1 —** $PA \\times PB = PC \\times PD$', `**Step 2 —** $${wd1.lines[0]}$, so $PC \\times PD = 60$`, `**Step 3 —** $PD = ${wd1.lines[1]}$ cm`], v: fWD1, n: 'Use the intersecting chords theorem. P A times P B is fifteen times four, which is sixty. This equals P C times P D, with P C equal to five. So P D is sixty divided by five, which is twelve centimetres.' }),
    sl('check', 'Quick check: two chords of a circle', { b: 'Equate the two products.', chk: 'm08', n: 'Two chords cut inside a circle. Equate the products of the parts to find the missing length.' }),
    sl('example', 'Worked example 2: chords with algebra', { b: 'Chords $AB$ and $CD$ cut at $P$ with $PA = 2x$, $PB = (x + 1)$, $PC = 2$ and $PD = 12$ (cm). Find $x$ and the lengths of the chords.', ul: [`**Step 1 —** ${wd2.md[0]}`, `**Step 2 —** $PA = ${wd2.lines[1]}$ cm and $PB = ${wd2.lines[2]}$ cm, so $AB = ${wd2.lines[3]}$ cm`, `**Step 3 —** $CD = ${wd2.lines[4]}$ cm`], v: fWD2, n: 'By the theorem, two x times x plus one equals two times twelve, which is twenty four. This simplifies to x squared plus x minus twelve equals zero, which factorises as x plus four times x minus three. A length cannot be negative, so x is three. Then P A is six and P B is four, so A B is ten centimetres. The chord C D is two plus twelve, fourteen centimetres.' }),
    sl('concept', 'Chords produced: secants from an outside point', { b: 'If the chords $AB$ and $CD$ are **produced** and meet at a point $P$ **outside** the circle, the same rule holds. Measure each secant from $P$ to the **far** end.', m: [r`PA \times PB = PC \times PD`], ul: [`here ${wsec.md[0]} and ${wsec.md[1]}`, 'the proof is the same: join $AD$ and $BC$ and use similar triangles'], v: fSec, n: 'Now let the chords be extended until they meet at a point P outside the circle. The same rule holds. Measure each secant from P to the far end. In the picture, five times twelve is sixty and six times ten is sixty. The proof is the same: join the points and use similar triangles.' }),
    sl('example', 'Worked example 3: two secants', { b: 'Two secants from $P$ meet the circle at $A$, $B$ and $C$, $D$. $PA = 5$ cm, $AB = 7$ cm and $PC = 6$ cm. Find $PD$ and $CD$.', ul: [`**Step 1 —** $PB = PA + AB = ${wd3.lines[0]}$ cm`, `**Step 2 —** $PA \\times PB = ${wd3.lines[1]}$, and this equals $PC \\times PD$: $PD = ${wd3.lines[2]}$ cm`, `**Step 3 —** $CD = PD - PC = ${wd3.lines[3]}$ cm`], v: fWD3, n: 'First find the far end of the first secant: P B is five plus seven, twelve. Then P A times P B is sixty, and it equals P C times P D. So P D is sixty divided by six, ten centimetres. The chord C D is the whole secant minus the outer part: ten minus six, four centimetres.' }),
    sl('concept', 'The tangent-secant theorem', { b: 'If a **tangent** $PT$ and a **secant** $PAB$ are drawn from the point $P$, then the **square of the tangent** equals the product of the secant and its outer part.', m: [r`PT^2 = PA \times PB`], ul: ['**Proof:** in $\\triangle PTA$ and $\\triangle PBT$, the angle at $P$ is common and $\\angle PTA = \\angle PBT$ (alternate segment theorem)', 'so the triangles are similar: $\\dfrac{PT}{PB} = \\dfrac{PA}{PT}$, giving $PT^2 = PA \\times PB$', `example: $${wts.lines[0]}$ and $${wts.lines[1]}$`], v: fTS, n: 'A tangent is the limiting case of a secant where the two points come together. The tangent secant theorem says the square of the tangent equals the product of the whole secant and its outer part. In the picture, the tangent is thirty centimetres, so its square is nine hundred. The secant gives twenty times forty five, which is also nine hundred. The proof uses similar triangles.' }),
    sl('example', 'Worked example 4: a chord from a tangent', { b: 'A tangent $PT = 20$ cm and a secant $PAB$ are drawn from $P$, with $PA = 16$ cm. Find the chord $AB$.', ul: [`**Step 1 —** $PT^2 = PA \\times PB$: $${wd4.lines[0]}$`, `**Step 2 —** $PB = ${wd4.lines[1]}$ cm`, `**Step 3 —** $AB = PB - PA = ${wd4.lines[2]}$ cm`], v: fWD4, n: 'The square of the tangent is twenty squared, four hundred. This equals P A times P B, with P A equal to sixteen. So P B is four hundred divided by sixteen, twenty five. The chord A B is the whole secant minus the outer part, twenty five minus sixteen, nine centimetres.' }),
    sl('check', 'Quick check: a tangent and a secant', { b: 'Square of the tangent equals product.', chk: 'm10', n: 'A tangent and a secant are drawn from one point. Use the square of the tangent to find the chord.' }),
    sl('example', 'Worked example 5: tangent and secant with algebra', { b: 'The tangent $PT = 9$ cm, and a secant $PAB$ has $PA = x$ cm and the chord $AB = 24$ cm. Find $x$.', ul: [`**Step 1 —** $PB = x + 24$ and $PT^2 = PA \\times PB$: ${wd5.md[0]}`, `**Step 2 —** $x > 0$, so $x = 3$ cm`, `**Step 3 —** check: $PB = ${wd5.lines[1]}$ cm and $${wd5.lines[2]}$, which equals $PT^2 = 81$`], v: fWD5, n: 'The whole secant is x plus twenty four, and the square of the tangent is eighty one. So x times x plus twenty four equals eighty one. That gives x squared plus twenty four x minus eighty one equals zero, which factorises as x plus twenty seven times x minus three. The length x is positive, so x is three. As a check, three times twenty seven is eighty one.' }),
    sl('concept', 'The alternate segment theorem', { b: 'The **angle between a tangent and a chord** through the point of contact is **equal to the angle in the alternate segment**, that is, the angle the chord makes at a point of the circle on the **other side** of the chord.', m: [r`\angle PTA = \angle TBA`], ul: ['the angle between the tangent and the chord and the angle in the alternate segment are $48^\\circ$ in the figure', 'the same holds on the other side: $\\angle QTA$ equals the angle in the opposite segment'], v: fAlt, n: 'Here is the alternate segment theorem. The angle between a tangent and a chord at the point of contact equals the angle in the alternate segment, that is, the angle made by the chord at a point on the other side of the chord. In the picture, the angle between the tangent and the chord is forty eight degrees, and so is the angle at B.' }),
    sl('concept', 'Proof of the alternate segment theorem', { b: 'Draw the diameter $TD$ through the point of contact $T$, and join $AD$.', ul: [`$\\angle PTD = 90^\\circ$ (tangent and radius) and $\\angle TAD = 90^\\circ$ (angle in a semicircle)`, `so $\\angle ATD = 90^\\circ - \\angle PTA$, and in $\\triangle TAD$: $\\angle TDA = 90^\\circ - \\angle ATD = \\angle PTA$`, `$\\angle TDA = \\angle TBA$ (same segment), so $\\angle PTA = \\angle TBA$`], v: fAltProof, n: 'To prove it, draw the diameter through T and join A to D. The tangent is perpendicular to the diameter, and the angle in a semicircle is ninety degrees. So the angle A T D is ninety minus the angle P T A. In the right angled triangle T A D, the angle at D is ninety minus the angle A T D, which is the angle P T A. The angle at D equals the angle at B, as both are in the same segment.' }),
    sl('check', 'Quick check: the alternate segment', { b: 'Which angle is it equal to?', chk: 'm12', n: 'What is the angle between a tangent and a chord equal to? Remember the other side of the chord.' }),
    sl('example', 'Worked example 6: a triangle inside a circle', { b: '$PQ$ is the tangent at $A$ to a circle through $A$, $B$, $C$, with $\\angle ACB = 68^\\circ$ and $\\angle ABC = 47^\\circ$. Find $\\angle PAB$, $\\angle QAC$ and $\\angle BAC$.', ul: ['**Step 1 —** alternate segment theorem: $\\angle PAB = \\angle ACB = 68^\\circ$', '**Step 2 —** in the same way $\\angle QAC = \\angle ABC = 47^\\circ$', `**Step 3 —** $\\angle BAC = ${wd6.lines[0]}$; check: $${wd6.lines[1]}$ on the straight line $PAQ$`], v: fWD6, n: 'By the alternate segment theorem, the angle P A B equals the angle A C B, sixty eight degrees. In the same way the angle Q A C equals the angle A B C, forty seven degrees. The angle B A C is then one hundred and eighty minus sixty eight minus forty seven, sixty five degrees. As a check, sixty eight plus sixty five plus forty seven makes one hundred and eighty, a straight line.' }),
    sl('check', 'Quick check: a tangent and a chord', { b: 'Use the alternate segment theorem.', chk: 'm13', n: 'A chord makes an angle with a tangent. Name the angle in the alternate segment that is equal to it.' }),
    sl('concept', 'Choosing between the theorems', { b: 'Decide from the **figure** which theorem applies, then write the equation.', v: fFlow2, n: 'To choose a theorem, look at the figure. Two chords crossing inside the circle, or two secants from an outside point, give the product rule. A tangent with a secant gives the square of the tangent. An angle between a tangent and a chord gives the alternate segment theorem.' }),
    sl('summary', 'Summary', { ul: ['Intersecting chords: $PA \\times PB = PC \\times PD$', 'Secants from an outside point: the same rule, measured from $P$ to the far ends', 'Tangent and secant: $PT^2 = PA \\times PB$', 'Alternate segment: tangent-chord angle equals the angle in the alternate segment', 'Combine with equal tangents, Pythagoras and the angle sum of a triangle'], v: tSum2, n: 'To sum up part two. Two intersecting chords, or two secants from an outside point, have equal products of segments. A tangent and a secant give the square of the tangent equals the product. The angle between a tangent and a chord equals the angle in the alternate segment. Real problems combine these with equal tangents, Pythagoras and the angle sum of a triangle.' }),
    sl('exam-tips', 'Exam tips: how marks are awarded', { ul: ['**Name the theorem (1 mark):** write "intersecting chords", "tangent-secant" or "alternate segment" beside the step', '**Equation (1 mark):** write the product or the equal angles before any numbers', '**Solve (1–2 marks):** simplify and, for a quadratic, reject the negative root', '**Mistake:** measuring a secant to the near point $A$ only instead of the far point $B$', '**Mistake:** taking the angle in the same segment instead of the alternate segment', '**Habit:** mark each new length or angle on the figure as you find it'], n: 'In the exam, name the theorem beside the step. Write the equation, the product or the equal angles, before putting in the numbers. If a quadratic appears, reject the negative root. Common slips are measuring a secant to the near point only instead of the far point, and using the same segment instead of the alternate segment. Mark each new length or angle on the figure as you find it.' }),
  ],
});

// ================================================================ notes
const cT = (n) => topic(n);
const notes = {
  unit: 'icse-10-mathematics-ch17', version: 1, title: 'Circles: Tangents, Secants and Intersecting Chords — chapter notes', language: 'en',
  sections: [
    { heading: '1. Tangent and radius', body_md: r`- A **tangent** meets a circle at exactly one point, the **point of contact**; a **secant** meets it at two points and a **chord** is the part of a secant inside the circle.
- **Theorem:** the tangent at a point is **perpendicular to the radius** drawn to the point of contact. *Proof:* every other point $X$ of the tangent is outside the circle, so $OX > OT$; $OT$ is the shortest segment from $O$ to the line, so it is perpendicular to it.
- Use it to get a right-angled triangle $OTP$: $PT = \sqrt{OP^2 - r^2}$.

*Example:* $OT = 20$ cm and $OP = 29$ cm give $PT = \sqrt{29^2 - 20^2} = 21$ cm; with $\angle POT = 62^\circ$, $\angle OPT = 180^\circ - 90^\circ - 62^\circ = 28^\circ$.`, key_terms: [{ term: 'Tangent', definition_md: 'A line that touches a circle at exactly one point.' }, { term: 'Secant', definition_md: 'A line that meets a circle at two points.' }, { term: 'Point of contact', definition_md: 'The one point that a tangent shares with the circle.' }], formulas: [{ latex: 'PT = \\sqrt{OP^2 - r^2}', label: 'Length of a tangent' }], visual: f4, visuals: [f3, fWE1, fWE2], topic_ids: [cT(1)] },
    { heading: '2. Two tangents from an external point', body_md: r`- The two tangents drawn to a circle from an **external point** are **equal**: $PA = PB$. *Proof:* the right-angled triangles $OAP$ and $OBP$ have $OA = OB$, the common side $OP$ and right angles at $A$ and $B$, so they are congruent (RHS).
- $OP$ bisects $\angle APB$ and $\angle AOB$, and $OP \perp AB$; in the quadrilateral $OAPB$: $\angle AOB = 180^\circ - \angle APB$.
- No tangent can be drawn from a point inside a circle.

*Example:* $\angle APB = 76^\circ$ gives $\angle AOB = 360^\circ - 90^\circ - 90^\circ - 76^\circ = 104^\circ$, $\angle OAB = \dfrac{180^\circ - 104^\circ}{2} = 38^\circ$ and $\angle PAB = 90^\circ - 38^\circ = 52^\circ$. For $PA = (3x - 4)$ cm and $PB = (x + 8)$ cm: $3x - 4 = x + 8$, $x = 6$.`, key_terms: [{ term: 'External point', definition_md: 'A point outside a circle; two tangents can be drawn from it.' }], formulas: [{ latex: '\\angle AOB = 180^\\circ - \\angle APB', label: 'Tangents from P' }], visual: f8, visuals: [fWE3, fWE4], topic_ids: [cT(2)] },
    { heading: '3. Touching circles', body_md: r`- Two circles **touch** when they meet at exactly one point; that point and the two centres lie on **one straight line** (the line of centres), and the common tangent at the point is perpendicular to it.
- **Externally:** the centres are on opposite sides of the point of contact and $d = r_1 + r_2$.
- **Internally:** the centres are on the same side of the point of contact and $d = r_1 - r_2$ (the smaller circle is inside).

*Example:* radii $3$ and $2$ cm touching externally are $3 + 2 = 5$ cm apart; radii $5$ and $2$ cm touching internally are $5 - 2 = 3$ cm apart. If $x + (x + 5) = 25$ then $x = 10$ and the radii are $10$ cm and $15$ cm.`, key_terms: [{ term: 'Line of centres', definition_md: 'The line through the centres of two circles; the point of contact of touching circles lies on it.' }], formulas: [{ latex: 'd = r_1 + r_2', label: 'Touch externally' }, { latex: 'd = r_1 - r_2', label: 'Touch internally' }], visual: fExt, visuals: [fInt, fWE5], topic_ids: [cT(2)] },
    { heading: '4. Common tangents', body_md: r`- A **common tangent** touches both circles. A **direct** one leaves both circles on the same side; a **transverse** one crosses the line of centres between the circles.
- Draw the radii to the points of contact and a line parallel to the tangent: the right-angled triangle has hypotenuse $d$ and a leg $r_1 - r_2$ (direct) or $r_1 + r_2$ (transverse).
- Direct: $\sqrt{d^2 - (r_1 - r_2)^2}$. Transverse: $\sqrt{d^2 - (r_1 + r_2)^2}$, which needs $d > r_1 + r_2$.

*Example:* $d = 25$, $r_1 = 11$, $r_2 = 4$: direct $\sqrt{25^2 - 7^2} = 24$, transverse $\sqrt{25^2 - 15^2} = 20$. For $r_1 = 18$, $r_2 = 3$ and $d = 25$ the direct tangent is $\sqrt{25^2 - 15^2} = 20$.`, key_terms: [{ term: 'Direct common tangent', definition_md: 'A common tangent with both circles on the same side of it.' }, { term: 'Transverse common tangent', definition_md: 'A common tangent that crosses the line of centres between the circles.' }], formulas: [{ latex: '\\sqrt{d^2 - (r_1 - r_2)^2}', label: 'Direct common tangent' }, { latex: '\\sqrt{d^2 - (r_1 + r_2)^2}', label: 'Transverse common tangent' }], visual: fCom, visuals: [fWE6], topic_ids: [cT(2)] },
    { heading: '5. Intersecting chords', body_md: r`- **Theorem:** if two chords $AB$ and $CD$ cut at $P$ inside a circle, $PA \times PB = PC \times PD$. *Proof:* $\triangle PAC \sim \triangle PDB$ (equal angles in the same segment), so $\dfrac{PA}{PD} = \dfrac{PC}{PB}$.
- If the chords are **produced** and meet at $P$ outside the circle, the same rule holds with $PB$ and $PD$ measured from $P$ to the far ends.
- Problems with algebra give a quadratic: reject the negative root, because a length is positive.

*Example:* $PA = 15$, $PB = 4$, $PC = 5$: $PD = \dfrac{15 \times 4}{5} = 12$ cm. For $PA = 2x$, $PB = x + 1$, $PC = 2$, $PD = 12$: $x^2 + x - 12 = 0$, $x = 3$. For secants, $PA = 5$, $AB = 7$, $PC = 6$ give $PD = \dfrac{5 \times 12}{6} = 10$ and $CD = 10 - 6 = 4$ cm.`, key_terms: [{ term: 'Intersecting chords', definition_md: 'Two chords that meet at a point; the products of their parts are equal.' }], formulas: [{ latex: 'PA \\times PB = PC \\times PD', label: 'Chords and secants' }], visual: fChords, visuals: [fProofCh, fWD1, fWD2, fSec, fWD3], topic_ids: [cT(3)] },
    { heading: '6. Tangent and secant', body_md: r`- **Theorem:** if a tangent $PT$ and a secant $PAB$ ($A$ nearer to $P$) are drawn from $P$, then $PT^2 = PA \times PB$. *Proof:* $\triangle PTA \sim \triangle PBT$ (common angle at $P$ and $\angle PTA = \angle PBT$), so $\dfrac{PT}{PB} = \dfrac{PA}{PT}$.
- The same square gives $PA \times PB = PC \times PD$ for two secants from the same point.
- If the secant passes through the centre, $AB$ is a diameter.

*Example:* $PT = 20$, $PA = 16$: $PB = \dfrac{400}{16} = 25$ and $AB = 25 - 16 = 9$ cm. For $PT = 9$, $PA = x$, $AB = 24$: $x(x + 24) = 81$, $x = 3$.`, key_terms: [{ term: 'Outer part', definition_md: 'The part $PA$ of a secant from the outside point $P$ to the near point $A$.' }], formulas: [{ latex: 'PT^2 = PA \\times PB', label: 'Tangent and secant' }], visual: fTS, visuals: [fWD4, fWD5], topic_ids: [cT(4)] },
    { heading: '7. The alternate segment theorem', body_md: r`- **Theorem:** the angle between a tangent and a chord through the point of contact equals the angle in the **alternate segment** (on the other side of the chord): $\angle PTA = \angle TBA$.
- *Proof:* draw the diameter $TD$: $\angle PTD = 90^\circ$ and $\angle TAD = 90^\circ$, so $\angle TDA = 90^\circ - \angle ATD = \angle PTA$, and $\angle TDA = \angle TBA$ (same segment).
- It gives all three angles of a triangle in a circle from the tangent at one vertex: with $\angle PAB = 68^\circ$ and $\angle QAC = 47^\circ$, $\angle BAC = 180^\circ - 68^\circ - 47^\circ = 65^\circ$.

*Example:* a tangent-chord angle of $48^\circ$ gives an angle of $48^\circ$ in the alternate segment and $2 \times 48^\circ = 96^\circ$ at the centre.`, key_terms: [{ term: 'Alternate segment', definition_md: 'The segment of the circle on the other side of the chord from the angle being considered.' }], formulas: [{ latex: '\\angle PTA = \\angle TBA', label: 'Alternate segment theorem' }], visual: fAlt, visuals: [fAltProof, fWD6], topic_ids: [cT(5)] },
  ],
  exam_tips_md: r`**How marks are awarded**
- *Length from a tangent (2–3 marks):* right angle named 1; Pythagoras line 1; answer with unit 1.
- *Proof of a theorem (3–4 marks):* construction 1; equal angles, sides or similar triangles 1–2; conclusion 1.
- *Product rule or tangent-secant (3–4 marks):* theorem named 1; equation 1; solving (and rejecting a negative root) 1; answer 1.
- *Alternate segment angles (3–4 marks):* the theorem named 1 each time it is used; angle sum or straight line 1; answer in degrees 1.
- *10-mark structured question:* parts (a), (b), (c), usually $3 + 3 + 4$; give the reason beside every step.

**Common mistakes**
1. Forgetting that the radius to the point of contact is perpendicular to the tangent.
2. Using the sum of the radii for circles that touch internally.
3. Measuring a secant from $P$ to the near point only; use $PB$, the far point, in $PA \times PB$.
4. Writing $PT = PA \times PB$ instead of $PT^2 = PA \times PB$.
5. Taking the angle in the same segment instead of the alternate segment.
6. Keeping the negative root of a quadratic for a length.`,
  status: 'draft', provenance: d1.provenance,
};
