A([r`\sqrt{29^2 - 20^2} = 21`, r`180^\circ - 90^\circ - 62^\circ = 28^\circ`, r`360^\circ - 90^\circ - 90^\circ - 76^\circ = 104^\circ`, r`\dfrac{180^\circ - 104^\circ}{2} = 38^\circ`, r`90^\circ - 38^\circ = 52^\circ`, r`3 + 2 = 5`, r`5 - 2 = 3`, r`\sqrt{25^2 - 7^2} = 24`, r`\sqrt{25^2 - 15^2} = 20`, r`\dfrac{15 \times 4}{5} = 12`, r`\dfrac{5 \times 12}{6} = 10`, r`10 - 6 = 4`, r`\dfrac{400}{16} = 25`, r`25 - 16 = 9`, r`180^\circ - 68^\circ - 47^\circ = 65^\circ`, r`2 \times 48^\circ = 96^\circ`], 'notes numbers');
W(eqctx('x', [6]), [r`3x - 4 = x + 8 \Rightarrow x = 6`], 'notes algebra 1');
W(eqctx('x', [10]), [r`x + (x + 5) = 25 \Rightarrow x = 10`], 'notes algebra 2');
